'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { generateArticleDraftAction } from './actions';

export default function ArticleDraftButton({ id }) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [message, setMessage] = useState('');

  function handleClick() {
    if (isPending) return;
    setMessage('Skriver et nytt privat utkast fra faktapakken …');

    startTransition(async () => {
      try {
        const formData = new FormData();
        formData.set('id', String(id));
        const result = await generateArticleDraftAction(formData);

        if (result?.ok && result?.articleId) {
          const checkText = result.tallValidert
            ? 'tallkontroll bestått'
            : 'lagret med et kontrollpunkt';
          setMessage(result.status === 'regenerated'
            ? 'Eksisterende utkast er skrevet på nytt. Går til utkastskøen …'
            : `Utkast lagret · ${checkText}. Går til utkastskøen …`);
          router.push('/redaksjon?tab=ko');
          return;
        }

        setMessage(result?.reason || 'Utkastet ble blokkert av faktakontrollen.');
        router.refresh();
      } catch (error) {
        console.error(error);
        setMessage('Artikkelmotoren stoppet. Ingen artikkel ble publisert.');
        router.refresh();
      }
    });
  }

  return (
    <div style={{ minWidth: 150 }}>
      <button type="button" className="adminLoadingButton" onClick={handleClick} disabled={isPending} aria-busy={isPending}>
        {isPending ? <><span className="adminSpinner" aria-hidden="true"/><span>Skriver utkast …</span></> : <span>Lag / regenerer utkast</span>}
      </button>
      {message ? <small aria-live="polite" style={{ display: 'block', marginTop: 6, maxWidth: 240 }}>{message}</small> : null}
    </div>
  );
}

'use client';

import { useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { runAutopilotStepAction } from './actions';

const STAGE_LABELS = {
  discovery: 'Henter nye saker',
  triage: 'Filtrerer og samler hendelser',
  scoring: 'AI-rangerer kandidater',
  selection: 'Velger toppsakene',
  research: 'Bygger kilde- og faktapakker',
  drafting: 'Skriver ferdige artikler',
  recovery: 'Prøver utsatt jobb på nytt',
  done: 'Ferdig',
};

function queueSummary(state) {
  if (!state) return '';
  return `Lokal filter: ${state.triagePending ? 'venter' : 'ferdig'} · AI-kandidater: ${state.scoring} · AI-retry: ${state.deferredScoring ?? 0} · Researchpool: ${state.selectionPending ? 'venter' : (state.selected ?? 0)} · Research igjen: ${state.research} (+${state.deferredResearch ?? 0} senere) · Skrevet: ${state.draftsCreated ?? 0}/${state.articleLimit ?? 3} · klare nå: ${state.drafting}`;
}

export default function AutopilotControl() {
  const router = useRouter();
  const stopRef = useRef(false);
  const [running, setRunning] = useState(false);
  const [stage, setStage] = useState('');
  const [message, setMessage] = useState('Klar. Den manuelle testkjøringen lager ferdige utkast. Den planlagte timekjøringen følger publiseringsbryteren over.');
  const [state, setState] = useState(null);
  const [processed, setProcessed] = useState(0);
  const [errors, setErrors] = useState([]);

  async function run() {
    if (running) return;

    stopRef.current = false;
    setRunning(true);
    setErrors([]);
    setProcessed(0);
    setStage('discovery');
    setMessage('Starter autopilot og henter nye radartreff …');

    let first = true;
    let activeRunId = null;
    let totalProcessed = 0;
    let stalled = 0;
    let lastProgressKey = '';
    let loops = 0;
    const collectedErrors = [];

    try {
      while (!stopRef.current && loops < 160) {
        loops += 1;
        const result = await runAutopilotStepAction({ discovery: first, runId: activeRunId });
        first = false;
        if (result?.runId) activeRunId = Number(result.runId);

        if (!result?.ok) {
          const newErrors = Array.isArray(result?.errors) ? result.errors : ['Ukjent autopilot-feil'];
          collectedErrors.push(...newErrors);
          setErrors([...collectedErrors]);
          setMessage(`Autopiloten stoppet: ${newErrors[0] || 'ukjent feil'}`);
          break;
        }

        const currentState = result.state || null;
        const amount = Number(result.processed || 0);
        totalProcessed += amount;
        setProcessed(totalProcessed);
        setState(currentState);
        setStage(result.stage || '');

        if (Array.isArray(result.errors) && result.errors.length) {
          collectedErrors.push(...result.errors);
          setErrors([...collectedErrors]);
        }

        const progressKey = currentState
          ? [result.stage, currentState.triagePending, currentState.scoring, currentState.deferredScoring, currentState.selectionPending, currentState.selected, currentState.research, currentState.deferredResearch, currentState.draftsCreated, currentState.drafting, currentState.deferredDrafting].join(':')
          : result.stage;

        if (result.stage === 'discovery') {
          const inserted = Number(result.discovery?.inserted || 0);
          const seen = Number(result.discovery?.seen || 0);
          setMessage(`Discovery ferdig: ${seen} treff sjekket, ${inserted} nye lagret. Lokal filtrering starter …`);
          stalled = 0;
        } else if (result.stage === 'triage') {
          const t = result.triage || {};
          setMessage(`Lokal trakt ferdig: ${Number(t.scanned || 0)} råtreff → ${Number(t.relevant || 0)} finansrelevante → ${Number(t.clusters || 0)} unike hendelser → ${Number(t.candidates || 0)} sendt videre til AI. ${Number(t.duplicates || 0)} duplikater og ${Number(t.noise || 0)} støytreff ble stoppet før AI.`);
          stalled = 0;
        } else if (result.stage === 'selection') {
          const selected = Array.isArray(result.selected) ? result.selected : [];
          const titles = selected.slice(0, 6).map((x) => '#' + x.rank + ' ' + x.title).join(' · ');
          setMessage(`Researchpool klar: ${selected.length} sterke hendelser undersøkes. Maks ${Number(result.articleLimit || 3)} av dem blir ferdige artikler.${titles ? ' ' + titles : ''}`);
          stalled = 0;
        } else if (result.stage === 'recovery') {
          const detail = Array.isArray(result.details) ? result.details[0] : null;
          setMessage(`Retry av tidligere utsatt ${detail?.kind === 'draft' ? 'utkast' : 'research'}: ${result.processed ? 'ferdig' : 'utsatt igjen'}.`);
          stalled = 0;
        } else {
          setMessage(`${STAGE_LABELS[result.stage] || 'Jobber'} · ${queueSummary(currentState)} · ${totalProcessed} arbeidssteg ferdig`);
          stalled = progressKey === lastProgressKey ? stalled + 1 : 0;
        }
        lastProgressKey = progressKey;

        if (result.stage === 'done') {
          const deferred = Number(currentState?.deferredScoring || 0)
            + Number(currentState?.deferredResearch || 0)
            + Number(currentState?.deferredDrafting || 0);
          setMessage(deferred > 0
            ? `Autopilot ferdig · ${totalProcessed} arbeidssteg behandlet · ${deferred} deljobber er utsatt til automatisk retry senere.`
            : `Autopilot ferdig · ${totalProcessed} arbeidssteg behandlet · denne redaksjonsrunden er ferdig.`);
          break;
        }

        if (stalled >= 3) {
          setMessage(`Autopiloten stoppet kontrollert fordi samme arbeid feilet flere ganger. ${queueSummary(currentState)}.`);
          break;
        }
      }

      if (stopRef.current) {
        setMessage(`Stoppet av deg. Alt som allerede er behandlet er lagret. ${queueSummary(state)}.`);
      } else if (loops >= 160) {
        setMessage('Autopiloten nådde sikkerhetsgrensen for denne kjøringen. Kjør den igjen for å fortsette resten.');
      }
    } catch (error) {
      const msg = error?.message || 'Ukjent feil';
      collectedErrors.push(msg);
      setErrors([...collectedErrors]);
      setMessage(`Autopiloten stoppet: ${msg}`);
    } finally {
      setRunning(false);
      router.refresh();
    }
  }

  function stop() {
    stopRef.current = true;
    setMessage('Stopper etter den deljobben som kjører nå …');
  }

  return (
    <div className="autopilotBox">
      <div className="autopilotTop">
        <div>
          <b>Autopilot · steg 1</b>
          <small>
            Ett klikk: discovery → lokal støyfiltrering og hendelsesklynger → maks ca. 45 AI-kandidater → researchpool på opptil 6 → de beste dokumenterte sakene blir maks 3 ferdige artikler. Automatisk publisering styres separat av bryteren over.
          </small>
        </div>
        <div className="autopilotActions">
          <button
            type="button"
            className="adminLoadingButton"
            onClick={run}
            disabled={running}
            aria-busy={running}
          >
            {running ? <span className="adminSpinner" aria-hidden="true"/> : null}
            <span>{running ? (STAGE_LABELS[stage] || 'Autopilot jobber …') : 'Kjør hele autopiloten'}</span>
          </button>
          {running ? (
            <button type="button" className="secondary" onClick={stop}>Stopp</button>
          ) : null}
        </div>
      </div>

      <div className="autopilotStatus" aria-live="polite">
        <span>{message}</span>
        {state ? <b>{queueSummary(state)}</b> : null}
        {processed > 0 ? <small>{processed} arbeidssteg fullført i denne kjøringen.</small> : null}
        {errors.length ? <small className="autopilotWarning">{errors.length} del-feil logget · siste: {errors[errors.length - 1]}</small> : null}
      </div>

      {state ? (
        <div className="autopilotProgressWrap">
          <div className="autopilotProgressMeta">
            <span>Fremdrift</span>
            <b>{Math.max(0, Math.min(100, Number(state.progressPct || 0)))}%</b>
          </div>
          <div className="autopilotProgress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow={Math.max(0, Math.min(100, Number(state.progressPct || 0)))}>
            <span style={{ width: `${Math.max(0, Math.min(100, Number(state.progressPct || 0)))}%` }}/>
          </div>
        </div>
      ) : null}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { setAutomationEnabledAction, setAutoPublishEnabledAction } from './actions';

function SwitchRow({ title, description, checked, busy, onToggle }) {
  return (
    <div className="editorialSwitchRow">
      <div>
        <b>{title}</b>
        <small>{description}</small>
      </div>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        className={`editorialSwitch ${checked ? 'on' : 'off'}`}
        disabled={busy}
        onClick={onToggle}
      >
        <span className="editorialSwitchKnob" />
        <strong>{checked ? 'PÅ' : 'AV'}</strong>
      </button>
    </div>
  );
}

export default function EditorialAutomationControls({ initialSettings }) {
  const [settings, setSettings] = useState({
    automationEnabled: initialSettings?.automationEnabled !== false,
    autoPublishEnabled: initialSettings?.autoPublishEnabled !== false,
  });
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');

  async function toggleAutomation() {
    if (busy) return;
    const next = !settings.automationEnabled;
    setBusy('automation');
    setError('');
    try {
      const result = await setAutomationEnabledAction(next);
      if (!result?.ok) throw new Error('Kunne ikke lagre innstillingen.');
      setSettings(result.settings);
    } catch (err) {
      setError(err?.message || 'Kunne ikke lagre innstillingen.');
    } finally {
      setBusy('');
    }
  }

  async function toggleAutoPublish() {
    if (busy) return;
    const next = !settings.autoPublishEnabled;
    setBusy('publish');
    setError('');
    try {
      const result = await setAutoPublishEnabledAction(next);
      if (!result?.ok) throw new Error('Kunne ikke lagre innstillingen.');
      setSettings(result.settings);
    } catch (err) {
      setError(err?.message || 'Kunne ikke lagre innstillingen.');
    } finally {
      setBusy('');
    }
  }

  return (
    <div className="editorialAutomationPanel">
      <div className="editorialAutomationHead">
        <div>
          <div className="sectionKicker">Automatisk redaksjon</div>
          <h3>To uavhengige brytere</h3>
        </div>
        <span className={settings.automationEnabled ? 'automationStatus on' : 'automationStatus off'}>
          {settings.automationEnabled ? 'TIMEKJØRING AKTIV' : 'TIMEKJØRING STOPPET'}
        </span>
      </div>

      <SwitchRow
        title="Nyhetsmotor"
        description="Planlagt redaksjonsrunde én gang i timen fra 06:00 til 23:00 norsk tid. AV er hovedbryteren og stopper nye automatiske steg."
        checked={settings.automationEnabled}
        busy={busy === 'automation'}
        onToggle={toggleAutomation}
      />

      <SwitchRow
        title="Automatisk publisering"
        description="PÅ publiserer ferdigskrevne og maskinvaliderte saker automatisk. AV skriver fortsatt sakene ferdig, men sender dem til køen for din godkjenning."
        checked={settings.autoPublishEnabled}
        busy={busy === 'publish'}
        onToggle={toggleAutoPublish}
      />

      {error ? <div className="automationError">{error}</div> : null}
    </div>
  );
}

'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { buildFactPackAction } from './actions';

export default function FactPackButton({ id, currentStatus }) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [message, setMessage] = useState('');

  function handleClick() {
    if (isPending) return;
    setMessage('Finner et godt kildegrunnlag og bygger faktapakke …');

    startTransition(async () => {
      try {
        const formData = new FormData();
        formData.set('id', String(id));
        const result = await buildFactPackAction(formData);

        if (result?.status === 'ready') {
          setMessage(`Ferdig · ${result.facts || 0} fakta · ${result.numbers || 0} tall · kvalitet ${result.confidence || 0}/100`);
        } else if (result?.status === 'needs_review') {
          setMessage(`Bygget, men trenger kontroll · kvalitet ${result.confidence || 0}/100`);
        } else if (result?.status === 'needs_source') {
          setMessage('Trenger et sterkere kildegrunnlag før artikkelskriving.');
        } else if (result?.status === 'insufficient_source') {
          setMessage('Offisiell kilde funnet, men den er for tynn til et sikkert artikkelutkast.');
        } else {
          setMessage('Faktapakken er oppdatert.');
        }

        router.refresh();
      } catch (error) {
        console.error(error);
        setMessage('Kunne ikke bygge faktapakken. Ingen artikkel ble skrevet.');
        router.refresh();
      }
    });
  }

  const label = currentStatus === 'ready'
    ? 'Bygg på nytt'
    : currentStatus
      ? 'Prøv faktapakke igjen'
      : 'Bygg faktapakke';

  return (
    <div style={{ minWidth: 145 }}>
      <button type="button" className="secondary adminLoadingButton" onClick={handleClick} disabled={isPending} aria-busy={isPending}>
        {isPending ? <><span className="adminSpinner" aria-hidden="true"/><span>Jobber …</span></> : <span>{label}</span>}
      </button>
      {message ? <small aria-live="polite" style={{ display: 'block', marginTop: 6, maxWidth: 220 }}>{message}</small> : null}
    </div>
  );
}

'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { manualCreateStoryAction } from './actions';

export default function ManualStoryButton({ id }) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [message, setMessage] = useState('');

  function handleClick() {
    setMessage('Finner kildegrunnlag og lager privat utkast …');
    startTransition(async () => {
      const result = await manualCreateStoryAction(id);
      if (result?.ok && result?.articleId) {
        setMessage('Utkast klart. Åpner saken …');
        router.push('/redaksjon/utkast/' + result.articleId);
        return;
      }
      setMessage(result?.error || 'Kunne ikke lage saken.');
      router.refresh();
    });
  }

  return (
    <div className="radarManualStory">
      <button
        type="button"
        className="secondary adminLoadingButton"
        onClick={handleClick}
        disabled={isPending}
        aria-busy={isPending}
      >
        {isPending ? <span className="adminSpinner" aria-hidden="true"/> : null}
        <span>{isPending ? 'Lager sak …' : 'Lag sak nå'}</span>
      </button>
      {message ? <small aria-live="polite">{message}</small> : null}
    </div>
  );
}

'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { runNewsRadarAction, scoreRadarItemsAction } from './actions';

export default function RadarActionControl({ mode }) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [message, setMessage] = useState('');

  const isRun = mode === 'run';
  const label = isRun ? 'Kjør radar nå' : 'Vurder nye treff';
  const pendingLabel = isRun ? 'Radaren jobber …' : 'AI vurderer …';

  function handleClick() {
    if (isPending) return;

    setMessage(isRun
      ? 'Henter, filtrerer og lagrer nye radartreff. Dette kan ta litt tid.'
      : 'Filtrerer lokalt først, deretter vurderer DeepSeek bare de sterkeste unike hendelsene.');

    startTransition(async () => {
      try {
        const result = isRun
          ? await runNewsRadarAction()
          : await scoreRadarItemsAction();

        if (isRun) {
          const seen = Number(result?.seen || 0);
          const inserted = Number(result?.inserted || 0);
          const globalSeen = Number(result?.globalSeen || 0);
          const globalInserted = Number(result?.globalInserted || 0);
          const errors = Array.isArray(result?.errors) ? result.errors : [];
          const warning = errors.length
            ? ` · ${errors.length} kildekall feilet: ${errors.slice(0, 3).join(' | ')}`
            : '';
          setMessage(`Ferdig. ${seen} treff sjekket, ${inserted} nye lagret · global indeks: ${globalSeen} treff / ${globalInserted} nye${warning}.`);
        } else {
          if (result?.ok === false) {
            setMessage(`Scoring stoppet: ${result?.error || 'ukjent feil'}`);
          } else {
            const requested = Number(result?.requested || 0);
            const scored = Number(result?.scored || 0);
            const triage = result?.triage || {};
            const errors = Array.isArray(result?.errors) ? result.errors : [];
            const warning = errors.length
              ? ` · ${errors.length} delbatch feilet: ${errors[0]}`
              : '';
            const funnel = triage.scanned != null
              ? `Lokal trakt: ${Number(triage.scanned || 0)} råtreff → ${Number(triage.clusters || 0)} unike hendelser → ${Number(triage.candidates || 0)} AI-kandidater. `
              : '';
            setMessage(`${funnel}AI vurderte ${scored} av ${requested}${warning}.`);
          }
        }

        router.refresh();
      } catch (error) {
        console.error(error);
        setMessage('Noe gikk galt under kjøringen. Siden er fortsatt trygg; prøv igjen eller sjekk status.');
        router.refresh();
      }
    });
  }

  return (
    <div style={{ minWidth: 170, textAlign: 'right' }}>
      <button type="button" className="adminLoadingButton" onClick={handleClick} disabled={isPending} aria-busy={isPending}>
        {isPending ? <><span className="adminSpinner" aria-hidden="true"/><span>{pendingLabel}</span></> : <span>{label}</span>}
      </button>
      {message ? (
        <small aria-live="polite" style={{ display: 'block', marginTop: 7, maxWidth: 240 }}>
          {message}
        </small>
      ) : null}
    </div>
  );
}

'use server';

import { redirect } from 'next/navigation';
import { revalidatePath } from 'next/cache';
import { approveDraft, archiveArticle, rejectDraft, setPinned, updateDraftArticle, createManualDraft } from '../../lib/admin-db';
import { syncNorgesBankFx } from '../../lib/sources/norges-bank';
import { syncNorgesBankPolicyRate } from '../../lib/sources/norges-bank-policy-rate';
import { syncEuronextOsloNews } from '../../lib/sources/euronext-oslo';
import { scorePendingRawItems } from '../../lib/ai/score-raw-items';
import { runNewsRadar } from '../../lib/radar/news-radar';
import { prepareRadarCandidates } from '../../lib/radar/local-triage';
import { scorePendingRadarItems } from '../../lib/ai/score-radar-items';
import { buildFactPackForRadarItem } from '../../lib/research/fact-pack';
import { generateArticleDraftFromRadar } from '../../lib/ai/write-article';
import { runAutopilotStep } from '../../lib/autopilot/autopilot';
import { setAutomationEnabled, setAutoPublishEnabled } from '../../lib/autopilot/editorial-settings';

async function requireAdmin() {
  // TEMPORARY DEVELOPMENT MODE:
  // Authentication is intentionally disabled until the site is ready to go live.
  return true;
}

export async function logoutAction() {
  redirect('/redaksjon');
}

export async function setAutomationEnabledAction(enabled) {
  await requireAdmin();
  const settings = await setAutomationEnabled(enabled === true);
  revalidatePath('/redaksjon');
  return { ok: true, settings };
}

export async function setAutoPublishEnabledAction(enabled) {
  await requireAdmin();
  const settings = await setAutoPublishEnabled(enabled === true);
  revalidatePath('/redaksjon');
  return { ok: true, settings };
}

export async function approveAction(formData) {
  await requireAdmin();
  await approveDraft(Number(formData.get('id')));
  revalidatePath('/');
  revalidatePath('/redaksjon');
}

export async function rejectAction(formData) {
  await requireAdmin();
  await rejectDraft(Number(formData.get('id')));
  revalidatePath('/redaksjon');
}

export async function archiveAction(formData) {
  await requireAdmin();
  await archiveArticle(Number(formData.get('id')));
  revalidatePath('/');
  revalidatePath('/redaksjon');
}

export async function pinAction(formData) {
  await requireAdmin();
  const id = Number(formData.get('id'));
  const pinned = String(formData.get('pinned')) === 'true';
  await setPinned(id, pinned);
  revalidatePath('/');
  revalidatePath('/redaksjon');
}

export async function syncNorgesBankAction() {
  await requireAdmin();
  await Promise.all([syncNorgesBankFx(), syncNorgesBankPolicyRate()]);
  revalidatePath('/');
  revalidatePath('/redaksjon');
}

export async function syncPolicyRateAction() {
  await requireAdmin();
  await syncNorgesBankPolicyRate();
  revalidatePath('/');
  revalidatePath('/redaksjon');
}

export async function syncEuronextOsloAction() {
  await requireAdmin();
  await syncEuronextOsloNews();
  revalidatePath('/redaksjon');
}

export async function scoreRawItemsAction() {
  await requireAdmin();
  try {
    await scorePendingRawItems(20);
    revalidatePath('/redaksjon');
  } catch (error) {
    console.error('Kapitalstrøm AI-scoring failed:', error);
    redirect('/api/ai-status');
  }
}

export async function runNewsRadarAction() {
  await requireAdmin();
  try {
    const result = await runNewsRadar();
    revalidatePath('/redaksjon');
    return { ok: true, ...result };
  } catch (error) {
    console.error('Kapitalstrøm news radar failed:', error);
    throw error;
  }
}

export async function scoreRadarItemsAction() {
  await requireAdmin();
  try {
    const triage = await prepareRadarCandidates();
    const result = await scorePendingRadarItems(30);
    revalidatePath('/redaksjon');
    return { ok: true, triage, ...result };
  } catch (error) {
    console.error('Kapitalstrøm radar scoring failed:', error);
    return {
      ok: false,
      error: error?.message || 'Ukjent feil under radarscoring.',
      requested: 0,
      scored: 0,
      errors: [error?.message || 'Ukjent feil'],
    };
  }
}

export async function buildFactPackAction(formData) {
  await requireAdmin();
  const id = Number(formData.get('id'));
  if (!Number.isFinite(id)) throw new Error('Ugyldig radartreff.');
  const result = await buildFactPackForRadarItem(id);
  revalidatePath('/redaksjon');
  return { ok: true, ...result };
}

export async function generateArticleDraftAction(formData) {
  await requireAdmin();
  const id = Number(formData.get('id'));
  if (!Number.isFinite(id)) throw new Error('Ugyldig radartreff.');
  const result = await generateArticleDraftFromRadar(id);
  revalidatePath('/redaksjon');
